    table(d,"__ent_kids_goal", cols("source_goal_id",DataType.TEXT,"category_item_ref",DataType.TEXT,"title_ka",DataType.MEMO,"title_en",DataType.MEMO,"path_ka",DataType.MEMO,"path_en",DataType.MEMO,"source_row_key",DataType.TEXT,"operation",DataType.TEXT));
