    Set<String> subs=new HashSet<>(), ages=new HashSet<>();
    for(Row row:legacy.getTable("files")){String id=s(row,"ID"), raw=raw(d,"files",id,row,++seq); d.getTable("__ent_kids_resource").addRow(id,requiredRef(category,s(row,"category"),"files",id),s(row,"title_geo"),s(row,"title_eng"),s(row,"path_geo"),s(row,"path_eng"),raw,"UPSERT"); int ordinal=0; for(String token:s(row,"sub_category").split(",",-1)){if(token.isEmpty())continue; String normalized=token.trim(); if(normalized.isEmpty())continue; String ref=subs.add(normalized)?item(d,SCHEME_SUB,normalized,null,null,"DRAFT"):itemRef(SCHEME_SUB,normalized); alias(d,ref,"KIDS_LEGACY_ACCESS",token,normalized,token.equals(normalized)?"NONE":"TRIM_FOR_LOOKUP_ONLY","DRAFT"); d.getTable("__rel_kids_resource_subcategory_assignment").addRow(id+"|"+(++ordinal),id,ref,token,ordinal,raw,"UPSERT");} carrierAndInputs(d,row,id,raw,ages);}
    Set<String> languages=new HashSet<>(); for(Row row:legacy.getTable("glossary")){String id=s(row,"ID"), lang=s(row,"lang"); String ref=languages.add(lang)?item(d,SCHEME_LANGUAGE,lang,lang.equals("ka")?"ქართული":null,lang.equals("en")?"English":null,lang.equals("ena")?"DRAFT":"READY"):itemRef(SCHEME_LANGUAGE,lang); alias(d,ref,"KIDS_LEGACY_ACCESS",lang,lang,"NONE",lang.equals("ena")?"DRAFT":"READY"); String raw=raw(d,"glossary",id,row,++seq);d.getTable("__ent_kids_glossary_entry").addRow(id,ref,lang,s(row,"text"),raw,"UPSERT");}
