  private static void carrierAndInputs(Database d,Row row,String id,String sourceRow,Set<String> ages)throws Exception {String payload=s(row,"chartdata"); if(payload.isBlank())return; String carrier="CARRIER|"+id; JsonNode array=null; String enc="DIRECT_JSON"; try{array=JSON.readTree(payload);}catch(Exception x){try{array=JSON.readTree(JSON.readValue("\""+payload.replace("\"","\\\"")+"\"",String.class));enc="ESCAPED_JSON_TEXT";}catch(Exception ignored){}} if(array==null||!array.isArray())return; Semantic semantic=SEMANTICS.get(id);if(semantic==null)throw new IllegalStateException("Missing governed semantic inference for carrier resource "+id);d.getTable("__raw_kids_statistical_carrier").addRow(carrier,id,sha(payload),"PARSED_ARRAY",sourceRow,"UPSERT");d.getTable("__stat_metric").addRow(semantic.metric(),id,s(row,"title_geo"),s(row,"title_eng"),"OBS_VALUE",semantic.unit(),"NONE","PROVISIONAL_APPROVED",semantic.confidence(),semantic.rationale());d.getTable("__rel_kids_statistical_semantic_binding").addRow(carrier,semantic.metric(),semantic.unit(),"NONE","A","F","KIDS_AGGREGATE_QUALITY_V1","KIDS_PUBLIC_AGGREGATE_V1","TITLE_RANGE_STANDARD_INFERENCE","UPSERT");int ordinal=0; for(int i=0;i<array.size();i++){JsonNode object=array.get(i);if(!object.isObject())continue;String period=object.path("year").asText();for(Iterator<Map.Entry<String,JsonNode>> it=object.fields();it.hasNext();){Map.Entry<String,JsonNode> e=it.next();if("year".equals(e.getKey())||e.getValue().isNull())continue;String key=e.getKey(),ref=ages.add(key)?item(d,SCHEME_AGE,key,null,null,"DRAFT"):itemRef(SCHEME_AGE,key);alias(d,ref,"KIDS_LEGACY_ACCESS",key,key.trim(),key.equals(key.trim())?"NONE":"TRIM_FOR_LOOKUP_ONLY","DRAFT");String lexical=e.getValue().asText();Double number;try{number=Double.valueOf(lexical);}catch(Exception ignored){number=null;}int n=++ordinal;d.getTable("__stat_kids_statistical_input").addRow(carrier+"|"+n,carrier,n,period,period.matches("[0-9]{4}")?period:null,key,ref,lexical,number,"$["+i+"]."+key,enc,sourceRow,"UPSERT");}}}
  private static void addUnits(Database d)throws Exception{Table t=d.getTable("__stat_unit");t.addRow("COUNT_EVENT","EVENT",1d,null,"Count of events");t.addRow("COUNT_CASE","CASE",1d,null,"Count of cases");t.addRow("PERSON","PERSON",1d,null,"Persons");t.addRow("THOUSAND_PERSONS","PERSON",1000d,null,"Thousand persons");t.addRow("THOUSAND_VISITS","VISIT",1000d,null,"Thousand visits");t.addRow("AVERAGE_NIGHTS","NIGHT",1d,"per visit","Average nights per visit");t.addRow("PER_100000_LIVE_BIRTHS","RATIO",1d,"100,000 live births","Per 100,000 live births");t.addRow("PER_1000_UNINFECTED_POPULATION","RATIO",1d,"1,000 uninfected population","Per 1,000 uninfected population");t.addRow("PER_100000_POPULATION","RATIO",1d,"100,000 population","Per 100,000 population");t.addRow("PERCENT","RATIO",.01d,"100 population","Percent");}
