  private static String raw(Database d,String table,String pk,Row row,int seq)throws Exception {String key=table+"|"+pk;String fileName=SOURCE_ARTIFACT==null?"":SOURCE_ARTIFACT.getName();String received=SOURCE_ARTIFACT==null?"":java.time.Instant.ofEpochMilli(SOURCE_ARTIFACT.lastModified()).toString();d.getTable("__raw_document").addRow(key,table,pk,seq,"KIDS_LEGACY_ACCESS","KIDS_PORTAL_EXPORT","KIDS_PORTAL_V1|R8|"+fileName,fileName,"application/vnd.ms-access",SOURCE_ARTIFACT==null?0:SOURCE_ARTIFACT.length(),SOURCE_CHECKSUM,received,SOURCE_ARTIFACT==null?"":SOURCE_ARTIFACT.getAbsolutePath(),"kids-portal-canonical-r8","{\"method\":\"read_only_access_extract\",\"sourceTable\":\""+table+"\",\"sourcePrimaryKey\":\""+pk+"\"}","ARCHIVE_1Y","PUBLIC_AGGREGATE","artifact://kids-portal-canonical-r8/"+fileName,"NONE","PARSED","PENDING","");return key;}
  private static String shaFile(File file)throws Exception{MessageDigest md=MessageDigest.getInstance("SHA-256");try(java.io.InputStream in=new java.io.FileInputStream(file)){byte[] buf=new byte[8192];for(int n;(n=in.read(buf))>0;)md.update(buf,0,n);}StringBuilder b=new StringBuilder();for(byte x:md.digest())b.append(String.format("%02x",x));return b.toString();}
