  private static void verify(Database d,Database source)throws Exception {long goals=count(source,"goals"),resources=count(source,"files"),glossary=count(source,"glossary"),categories=count(source,"goals_titles");expect(d,"__raw_document",goals+resources+glossary+categories);expect(d,"kids_goal",goals);expect(d,"kids_resource",resources);expect(d,"kids_glossary_entry",glossary);long carriers=count(d,"kids_statistical_carrier");expect(d,"__stat_metric",carriers);expect(d,"kids_statistical_semantic_binding",carriers);if(count(d,"__stat_unit")!=10||count(d,"kids_resource_subcategory_assignment")==0||carriers==0||count(d,"kids_statistical_input")==0)throw new IllegalStateException("Canonical reference/relation/statistical datasets are empty");if(carriers>resources)throw new IllegalStateException("A resource cannot have more than one statistical carrier");if(d.getRelationships().size()!=21)throw new IllegalStateException("Expected 21 enforced Access relationships, got "+d.getRelationships().size());}
